$ErrorActionPreference = 'Stop'
$path = 'src\editors\website\WebsiteEditor.tsx'
if (!(Test-Path $path)) { throw 'Run this from the Onyx Studio project root.' }
$expected = '66BFDFDA20B9AC380E09F7C34BCC44F7694E34B649849A769451B357DCE9E787'
if ((Get-FileHash $path -Algorithm SHA256).Hash -ne $expected) {
  throw 'Your WebsiteEditor.tsx differs from the uploaded version. No changes made.'
}
$backup = "$path.$(Get-Date -Format yyyyMMdd-HHmmss).bak"
Copy-Item $path $backup
try {
  $data = ''
  [System.IO.File]::WriteAllBytes((Resolve-Path $path).Path, [Convert]::FromBase64String($data))
  npm run build
  if ($LASTEXITCODE -ne 0) { throw 'Build failed.' }
  Write-Host 'Smart Guides v2 installed and build passed.' -ForegroundColor Green
} catch {
  Copy-Item $backup $path -Force
  Write-Host 'Restored original editor.' -ForegroundColor Yellow
  throw
}
